import { provide, ref } from 'vue';
import AppLayout from './components/AppLayout.vue';
export default {
  name: 'App',
  components: {
    AppLayout
  },
  setup() {
    const user = ref(null);
    const setUser = userData => {
      user.value = userData;
    };
    provide('user', user);
    provide('setUser', setUser);
    return {
      user,
      setUser
    };
  }
};
